// Route `supabase.auth.getUser()` through the locally cached session instead
// of hitting `/auth/v1/user` on every call. The codebase has ~167 getUser()
// call sites that only need "who is signed in right now" — server-side
// re-validation is unnecessary for those reads and was driving 5k+ auth
// requests/hour on a Nano compute, saturating the DB. getSession() reads
// from localStorage; autoRefreshToken still keeps the token fresh in the
// background. Revert by deleting this block if true server validation is
// ever needed in a specific call path.
const _originalGetUser = supabase.auth.getUser.bind(supabase.auth);
supabase.auth.getUser = (async (jwt?: string) => {
  if (jwt) {
    return _originalGetUser(jwt);
  }
  const { data: { session }, error } = await supabase.auth.getSession();
  return { data: { user: session?.user ?? null }, error };
}) as typeof supabase.auth.getUser;